package ua.aia2.guard;
import net.minecraft.world.level.block.entity.BlockEntity;
public final class Aia2MachineGuard {
 public static final GuardPolicy policy=new GuardPolicy();private static final ThreadLocal<BlockEntity> context=new ThreadLocal<>();
 public static boolean mayTick(BlockEntity block){return policy.getRequiredStage(block.state.id())<=1 || policy.isReady()&&policy.mayTick(block.state.id(),block.owner);}
 public static BlockEntity enterTick(BlockEntity block){var before=context.get();context.set(block);return before;}
 public static void exitTick(BlockEntity before){if(before==null)context.remove();else context.set(before);}
 public static BlockEntity currentTickOwner(){return context.get();}
 public static boolean mayProcessStage(int stage){var owner=context.get();return owner!=null&&policy.mayUseStage(stage,owner.owner);}
}
